use crate::{domain::wallet::{WalletStats, WalletTradeObservation, WalletTier}, smart_money::{score_wallet, SmartMoneyThresholds}}; use chrono::{DateTime, Duration, Utc}; use std::collections::{HashMap, HashSet};
#[derive(Default)] pub struct WalletTracker { wallets: HashMap<String, WalletStats>, observations: Vec<WalletTradeObservation>, thresholds: SmartMoneyThresholds }
impl WalletTracker { pub fn new(thresholds: SmartMoneyThresholds) -> Self { Self { thresholds, ..Self::default() } } pub fn upsert(&mut self, mut stats: WalletStats) { score_wallet(&mut stats, &self.thresholds); self.wallets.insert(stats.wallet.clone(), stats); } pub fn observe(&mut self, observation: WalletTradeObservation) { self.observations.push(observation); }
    /// Uses only observations available at `as_of`; entity_id is deliberately
    /// deduplicated so known linked wallets cannot manufacture consensus.
    pub fn qualified_consensus_at(&self, mint: &str, as_of: DateTime<Utc>, max_age: Duration) -> Vec<&WalletStats> { let mut entities=HashSet::new(); self.observations.iter().filter(|o| o.mint==mint && matches!(o.side,crate::domain::wallet::Side::Buy) && o.observed_at<=as_of && o.received_at<=as_of && as_of-o.observed_at<=max_age).filter_map(|o|self.wallets.get(&o.wallet)).filter(|w|matches!(w.tier,WalletTier::Qualified|WalletTier::HighConfidence) && w.updated_at<=as_of && as_of-w.updated_at<=max_age).filter(|w|entities.insert(w.entity_id.clone().unwrap_or_else(||format!("wallet:{}",w.wallet)))).collect() }
    pub fn qualified_consensus(&self,mint:&str)->Vec<&WalletStats>{self.qualified_consensus_at(mint,Utc::now(),Duration::minutes(15))}
}
